import{_ as o,o as s,c as i,a2 as t}from"./chunks/framework.Cdp8-jB6.js";const u=JSON.parse('{"title":"Mobile app — build, run, deploy (contributor guide)","description":"","frontmatter":{},"headers":[],"relativePath":"guides/mobile-build-and-deploy.md","filePath":"guides/mobile-build-and-deploy.md"}'),a={name:"guides/mobile-build-and-deploy.md"};function n(r,e,d,l,c,h){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="mobile-app-—-build-run-deploy-contributor-guide" tabindex="-1">Mobile app — build, run, deploy (contributor guide) <a class="header-anchor" href="#mobile-app-—-build-run-deploy-contributor-guide" aria-label="Permalink to &quot;Mobile app — build, run, deploy (contributor guide)&quot;">​</a></h1><p><em>PRD-015 / RFC-018 · ADR-078 (iOS-first + stream-heavy) · ADR-079 (assetUrl spine) · v0.8</em></p><p>The operator-side companion to PRD-015 + RFC-018. How a contributor builds the Capacitor iOS/Android app, runs it on a simulator/device, and ships it — plus the sharp edges this codebase hit on the first on-device run so you don&#39;t re-discover them.</p><blockquote><p><strong>The web app is the product.</strong> Capacitor wraps the SvelteKit static <code>build/</code> in a WKWebView (iOS) / Chromium WebView (Android). There is no native UI. The <code>android/</code> and <code>ios/</code> directories are committed (Capacitor convention).</p></blockquote><blockquote><p><strong>Validating your changes:</strong> see <strong><a href="/orrery/docs/guides/mobile-testing">Mobile testing strategy</a></strong>. <code>npm run test:e2e:mobile</code> (device-free, in CI) asserts the streaming contract + size budget on the pruned bundle; the guide&#39;s Layer 3 checklist covers the on-device bits before a mobile release.</p></blockquote><hr><h2 id="_1-·-prerequisites" tabindex="-1">1 · Prerequisites <a class="header-anchor" href="#_1-·-prerequisites" aria-label="Permalink to &quot;1 · Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Target</th><th>Toolchain</th><th>Notes</th></tr></thead><tbody><tr><td><strong>iOS</strong></td><td>Xcode 26+, CocoaPods (<code>brew install cocoapods</code>)</td><td>Accept the Xcode licence: <code>sudo xcodebuild -license accept</code>. <code>pod</code> uses system Ruby — install via brew, not gem.</td></tr><tr><td><strong>Android</strong></td><td>JDK <strong>21</strong> (<code>brew install --cask temurin@21</code>), Android Studio + SDK 35, an <strong>arm64</strong> emulator image</td><td>Capacitor 8 requires JDK 21. <code>export JAVA_HOME=&quot;$(/usr/libexec/java_home -v 21)&quot;</code>. Android Studio bundles its own JDK for the emulator.</td></tr><tr><td><strong>Both</strong></td><td>Node 20+, <code>npm install</code></td><td>Capacitor 8.4.1.</td></tr></tbody></table><p>Verify: <code>xcodebuild -version &amp;&amp; pod --version</code> (iOS) · <code>java -version &amp;&amp; adb --version</code> (Android).</p><hr><h2 id="_2-·-the-build-→-sync-→-run-loop" tabindex="-1">2 · The build → sync → run loop <a class="header-anchor" href="#_2-·-the-build-→-sync-→-run-loop" aria-label="Permalink to &quot;2 · The build → sync → run loop&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:mobile</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # MOBILE=1 build + prune + downscale + budget gate (~47 MB on-device)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # copy build/ into ios/ + android/, install pods/plugins</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ios</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;simulator-udid&gt;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # build + deploy + launch (iOS)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> android</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;emulator-name&gt;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # (Android)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or open the native IDE:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open:ios</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # npx cap open ios</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open:android</span></span></code></pre></div><ul><li><strong><code>build:mobile</code></strong> is a 4-step chain (each <code>MOBILE=1</code>, since env doesn&#39;t cross <code>&amp;&amp;</code>): <code>build</code> → <code>prune-streamed-assets.mjs</code> (strips <code>build/images</code>, <code>build/audio</code>, the 13 non-default locale HTML trees + bundles + raw i18n, dead <code>.br/.gz</code>, and the 4K LOD textures) → <code>downscale-base-textures.mjs</code> (io/titan/enceladus/pluto in place) → <code>check-mobile-size-budget.mjs</code> (fails over 65 MB). Takes a ~2 GB naive build down to <strong>~47 MB</strong>.</li><li><strong>Simulator UDIDs:</strong> <code>xcrun simctl list devices available | grep iPhone</code>. Boot one: <code>xcrun simctl boot &lt;udid&gt;</code>.</li><li><strong>Screenshot (headless):</strong> <code>xcrun simctl io &lt;udid&gt; screenshot /tmp/x.png</code> (iOS) · <code>adb exec-out screencap -p &gt; /tmp/x.png</code> (Android).</li></ul><h3 id="local-dev-—-live-reload-from-a-local-server-100-offline" tabindex="-1">Local dev — live-reload from a local server (100% offline) <a class="header-anchor" href="#local-dev-—-live-reload-from-a-local-server-100-offline" aria-label="Permalink to &quot;Local dev — live-reload from a local server (100% offline)&quot;">​</a></h3><p>The build → sync → run loop above installs a <strong>release-shaped bundle</strong> that streams heavy assets (images/audio/other-locale bundles) from <code>STREAM_ORIGIN</code> — i.e. the <em>deployed</em> host. On a fresh machine, or before that host has the current assets, galleries render blank (the app asks for <code>…/01.webp</code>, the CDN only has <code>…/01.jpg</code> → 404). That&#39;s deploy skew, not a bug. For day-to-day dev you don&#39;t want to stream from anywhere — you want everything from your own machine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># terminal 1 — local dev server (serves the whole app incl. webp images)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                          # honours VITE_DEV_PORT (default 5273)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># terminal 2 — pick your platform</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:android</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # sets adb reverse + CAP_DEV_SERVER, runs on the emulator</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:ios</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # runs on the booted simulator</span></span></code></pre></div><ul><li><strong><code>CAP_DEV_SERVER</code></strong> (read by <code>capacitor.config.ts</code>) points the WebView at the local dev server instead of the bundle. Set → live-reload; unset → release bundle. Both <code>dev:*</code> scripts set it to <code>http://localhost:\${VITE_DEV_PORT:-5273}</code>.</li><li><strong><code>localhost</code> works for both platforms with zero internet:</strong> the iOS simulator shares the Mac&#39;s <code>localhost</code> natively (and iOS ATS exempts <code>localhost</code>, so plain http is fine); the Android emulator can&#39;t reach the host&#39;s loopback directly, so <code>dev:android</code> runs <code>adb reverse tcp:&lt;port&gt; tcp:&lt;port&gt;</code> first. No LAN IP, no CDN, no <code>10.0.2.2</code>.</li><li>In dev the app runs as a <strong>browser build</strong> (<code>__MOBILE__</code> false), so images are origin-relative → served by the dev server. Nothing is pruned or streamed.</li><li><strong>Prod origin is configurable, not hardcoded</strong> (<code>STREAM_ORIGIN</code> env → vite define): a release build points at whatever host it&#39;ll be served from — GitHub Pages today, a VPS IP next, a domain later — via one env var, e.g. <code>STREAM_ORIGIN=https://&lt;host&gt; npm run build:mobile</code>. Web builds ignore it entirely (they stream origin-relative from their own host). See <code>src/lib/asset-url.ts</code>.</li></ul><blockquote><p>The dev server ignores <code>android/</code> + <code>ios/</code> in its file watcher (<code>vite.config.ts</code><code>server.watch.ignored</code>) — otherwise <code>cap sync</code> writing into those dirs triggers Vite dep re-optimization mid-session, which breaks route-chunk loading in the WebView.</p></blockquote><hr><h2 id="_3-·-how-streaming-works-why-the-bundle-is-47-mb-not-2-gb" tabindex="-1">3 · How streaming works (why the bundle is ~47 MB, not 2 GB) <a class="header-anchor" href="#_3-·-how-streaming-works-why-the-bundle-is-47-mb-not-2-gb" aria-label="Permalink to &quot;3 · How streaming works (why the bundle is ~47 MB, not 2 GB)&quot;">​</a></h2><p>The naive build is ~2 GB — 10× the iOS 200 MB OTA cap. So (ADR-078 / ADR-079):</p><ul><li><strong>Bundled on-device:</strong> code, planet textures, core mission/site/fleet JSON, the <strong>en-US</strong> locale bundle.</li><li><strong>Streamed from <code>chipi.github.io/orrery</code></strong> (SW-cached on first view): all gallery/hero imagery, narration audio, the other 13 locale bundles.</li></ul><p>The switch is <code>src/lib/asset-url.ts</code> — <code>assetOrigin</code> / <code>assetUrl()</code> / <code>streamedUrl()</code> / <code>localeBundleOrigin()</code> resolve to the CDN origin <strong>only when <code>__MOBILE__</code> is true</strong> (a Vite <code>define</code>, <code>MOBILE=1</code>). In every browser build <code>assetOrigin === base</code>, so URLs are byte-identical. When adding a new consumer of <code>/images/…</code> or <code>/audio/…</code>, <strong>route it through <code>assetUrl</code>/<code>streamedUrl</code></strong> or it 404s on mobile (the panorama <code>swapTexture</code> bug was exactly this).</p><p><strong>Trade-off (PRD-015 M5):</strong> core experience works offline from install; galleries + audio need one online view to cache.</p><hr><h2 id="_4-·-sharp-edges-learned-the-hard-way-2026-07-07" tabindex="-1">4 · Sharp edges (learned the hard way, 2026-07-07) <a class="header-anchor" href="#_4-·-sharp-edges-learned-the-hard-way-2026-07-07" aria-label="Permalink to &quot;4 · Sharp edges (learned the hard way, 2026-07-07)&quot;">​</a></h2><ul><li><strong><code>env(safe-area-inset-*)</code> returns 0 in Capacitor iOS.</strong> The nav/footer render under the status bar / Dynamic Island. Fixed by a native shim — <code>SafeAreaViewController</code> (<code>ios/App/App/AppDelegate.swift</code>, wired via <code>Main.storyboard</code>) injects the real <code>view.safeAreaInsets</code> as CSS vars; CSS reads <code>var(--safe-area-inset-top, env(...))</code>. Don&#39;t trust <code>env()</code> here; <strong>instrument</strong> the computed value on-screen when debugging.</li><li><strong><code>ios.scrollEnabled</code> config isn&#39;t reliably applied.</strong> The shim also forces <code>webView.scrollView.isScrollEnabled = true</code>. Config alone left touch-scroll dead (programmatic scroll worked — the tell).</li><li><strong><code>capacitor-assets generate</code> errors on the PWA step</strong> (looks for <code>www/manifest.json</code>). Use <code>--ios</code> / <code>--android</code> flags to scope it; it still generates the native icons/splash. Source art: <code>assets/icon.png</code> (1024) + <code>assets/splash.png</code> (2732) rendered from <code>static/favicon.svg</code> via <code>sharp</code>. It also drops a stray <code>icons/</code> at repo root — delete it.</li><li><strong>Splash flashes by unseen</strong> without <code>@capacitor/splash-screen</code>. Installed + <code>launchShowDuration: 1800</code>.</li><li><strong>macOS lockfile trap:</strong> an incremental <code>npm i &lt;pkg&gt;</code> on macOS can strip Linux-only optionals (<code>@rollup/rollup-linux-*</code>) from <code>package-lock.json</code> → CI <code>npm ci</code> fails on Linux. After adding a dep, <code>git diff package-lock.json | grep &#39;^-.*linux&#39;</code> and grep-confirm <code>@rollup/rollup-linux-x64-gnu</code> survives (a full <code>rm lock &amp;&amp; npm install</code> regen usually restores them; verify).</li><li><strong>tech-bom license gate:</strong> <code>@capacitor/assets</code> pulls <code>@trapezedev/*</code> (MIT, but <code>package.json</code> says non-SPDX &quot;SEE LICENSE&quot;). Add to <code>PACKAGE_LICENSE_OVERRIDES</code> in <code>scripts/build-tech-bom.ts</code>, then <code>npm run build-tech-bom</code>.</li><li><strong>Locale flags</strong> were dropped — flag emoji tofu (&quot;?&quot;) on the iOS Simulator (and Windows). The <code>EN/ES/FR</code> shortTag stays.</li></ul><hr><h2 id="_5-·-ship-—-ios-testflight-s13" tabindex="-1">5 · Ship — iOS TestFlight (S13) <a class="header-anchor" href="#_5-·-ship-—-ios-testflight-s13" aria-label="Permalink to &quot;5 · Ship — iOS TestFlight (S13)&quot;">​</a></h2><p>CI does <strong>not</strong> build the native binaries (no Xcode/Android SDK in the runners); mobile builds are local. Version lives in <code>package.json</code> (0.8.0-wip → PWA/footer), iOS <code>MARKETING_VERSION</code> (numeric, Apple requires it), Android <code>versionName</code>.</p><ol><li><code>npm run sync:mobile</code> (build:mobile + cap sync).</li><li><code>npm run open:ios</code> → in Xcode, select the <strong>App</strong> target → Signing &amp; Capabilities → set your Apple Developer <strong>Team</strong> (auto-manage signing). This step needs your Apple ID; it can&#39;t be scripted here.</li><li>Product → Archive → Distribute App → App Store Connect → upload.</li><li>In App Store Connect, create the app record (bundle id <code>io.github.chipi.orrery</code>); it appears in <strong>TestFlight</strong> for internal testers.</li></ol><p><strong>Android (later):</strong> <code>npm run open:android</code> → Build → Generate Signed App Bundle → upload the <code>.aab</code> to Play Console (Internal Testing track). Needs JDK 21.</p><hr><h2 id="_6-·-deep-links-share" tabindex="-1">6 · Deep links + share <a class="header-anchor" href="#_6-·-deep-links-share" aria-label="Permalink to &quot;6 · Deep links + share&quot;">​</a></h2><ul><li><strong>Deep links:</strong> <code>orrery://fly?mission=curiosity</code> → <code>/fly?mission=curiosity</code>. Scheme registered in <code>ios/App/App/Info.plist</code> (<code>CFBundleURLTypes</code>) + <code>AndroidManifest.xml</code> (intent-filter); handled in <code>src/lib/native/deep-links.ts</code>.</li><li><strong>Share:</strong> the nav share button (<code>src/lib/share.ts</code>) → native share sheet on Capacitor, <code>navigator.share</code> on web, copy-link fallback. It shares a <strong>public</strong> <code>chipi.github.io/orrery/&lt;route&gt;</code> URL (not the internal <code>capacitor://localhost</code> one).</li></ul><hr><h2 id="_7-·-architecture-map" tabindex="-1">7 · Architecture map <a class="header-anchor" href="#_7-·-architecture-map" aria-label="Permalink to &quot;7 · Architecture map&quot;">​</a></h2><p>See <strong><a href="./../adr/TA">TA.md §Mobile subsystem</a></strong> for the full component map, and:</p><ul><li><strong>ADR-078</strong> — iOS-first + stream-heavy bundle</li><li><strong>ADR-079</strong> — <code>assetUrl()</code> origin spine + source/derived separation</li><li><strong>RFC-018</strong> — the Capacitor integration (read the v0.5 correction notes)</li><li><strong>#195</strong> — WebGL context-loss (shipped reload; per-scene reinit deferred)</li></ul><hr><p><em>Orrery · docs/guides/mobile-build-and-deploy.md · July 2026</em></p>`,41)])])}const g=o(a,[["render",n]]);export{u as __pageData,g as default};
